        cmd(squashed ? 'git push -u --force-with-lease origin ' + branchName : 'git push -u origin ' + branchName);
    } catch (pushError) {
        console.warn('Normal push failed; synchronizing with origin/' + branchName + ' before retry:', pushError.message || pushError);
